      { question: "Which SQL sub-language includes CREATE, ALTER, and DROP?", options: ["DML", "DDL", "DCL", "TCL"], answer: 1, explanations: ["DML is INSERT/UPDATE/DELETE/SELECT.", "Correct — DDL (Data Definition Language) includes CREATE, ALTER, DROP for defining structure.", "DCL is GRANT/REVOKE.", "TCL is COMMIT/ROLLBACK."], difficulty: "easy" },
      { question: "Are SQL keywords case-sensitive?", options: ["Yes", "No — SELECT = select", "Only in MySQL", "Only in PostgreSQL"], answer: 1, explanations: ["They're case-insensitive.", "Correct — SQL keywords are case-insensitive: SELECT, select, Select are all the same. String values are case-sensitive.", "Not MySQL-specific.", "Not PostgreSQL-specific."], difficulty: "easy" }
